"""Build a portable, offline interactive HTML dashboard from computed analysis outputs."""
from pathlib import Path
import json
from plotly.offline.offline import get_plotlyjs
ROOT=Path(__file__).resolve().parents[1]
metrics=json.loads((ROOT/'outputs'/'metrics.json').read_text())
agg=json.loads((ROOT/'outputs'/'dashboard_aggregates.json').read_text())
import pandas as pd
causes=pd.read_csv(ROOT/'outputs'/'root_causes.csv').to_dict(orient='records')
html=r'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Operations Control | Lending Workflow Assessment</title><style>
:root{--bg:#f5f7fa;--paper:#fff;--ink:#122237;--muted:#64748b;--line:#e1e7ef;--nav:#101e32;--accent:#137f82;--violet:#6674be;--warn:#a85b28;--good:#168366}*{box-sizing:border-box}body{margin:0;font:14px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:var(--ink);background:var(--bg)}header{background:var(--nav);color:white;padding:27px max(24px,calc((100vw - 1300px)/2));}header .eyebrow{font-size:11px;letter-spacing:2.2px;font-weight:700;color:#90d5d1;text-transform:uppercase}header h1{font-size:30px;line-height:1.2;margin:8px 0}header p{margin:0;color:#b8c8d8;max-width:820px}main{max-width:1300px;margin:0 auto;padding:24px} .toolbar{display:flex;flex-wrap:wrap;align-items:end;justify-content:space-between;gap:12px;margin-bottom:18px}.controls{display:flex;gap:10px;flex-wrap:wrap}.control{display:flex;flex-direction:column;gap:5px;font-size:11px;color:var(--muted);font-weight:700;letter-spacing:.3px}select,input[type=range]{border:1px solid #d4dde8;background:white;border-radius:9px;padding:9px 12px;color:var(--ink);min-width:145px;font-size:13px}.tag{background:#e4f2f0;color:#216e6c;border-radius:99px;padding:7px 11px;font-size:11px;font-weight:750;white-space:nowrap}.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.card,.panel{background:var(--paper);border:1px solid var(--line);border-radius:14px;box-shadow:0 3px 20px rgba(16,30,50,.028)}.card{padding:18px 17px}.card .cap{text-transform:uppercase;letter-spacing:1.3px;color:var(--muted);font-size:10px;font-weight:750}.card .val{font-size:29px;letter-spacing:-.9px;font-weight:760;margin-top:4px}.card .note{color:var(--muted);font-size:11px;line-height:1.4;margin-top:1px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:15px}.panel{padding:18px 20px}.panel h2{font-size:15px;margin:0}.panel .sub{font-size:12px;color:var(--muted);margin:3px 0 7px}.chart{height:286px}.lower{display:grid;grid-template-columns:1.15fr .85fr;gap:14px;margin-top:15px}.sliders{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.scenario{background:#ecf7f5;border:1px solid #cce5e1;border-radius:12px;padding:14px 16px;margin-top:16px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.scenario b{font-size:22px;display:block}.scenario small{font-size:11px;color:#456967}.mini{font-size:12px;color:var(--muted)}.note-block{background:#f7f9fc;border-left:3px solid var(--accent);border-radius:0 9px 9px 0;padding:11px 13px;margin-top:14px;font-size:12px}.steps{display:grid;gap:12px;margin-top:14px}.step{display:flex;gap:10px;align-items:flex-start}.num{border-radius:7px;background:#e8efef;color:#137f82;font-weight:700;padding:3px 9px}.step b{display:block}.step p{margin:2px 0;color:var(--muted);font-size:12px}footer{color:var(--muted);font-size:11px;padding:26px 0;text-align:center}.badge{display:inline-block;padding:3px 8px;border-radius:99px;background:#fff1e5;color:#a85b28;font-size:10px;font-weight:700;margin-left:6px}@media(max-width:1100px){.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){header h1{font-size:24px}.kpis{grid-template-columns:repeat(2,1fr)}.grid,.lower{grid-template-columns:1fr}.sliders{grid-template-columns:1fr}.scenario{grid-template-columns:1fr}.chart{height:270px}main{padding:14px}}
</style></head><body><header><div class="eyebrow">Portfolio case study / Business operations intelligence</div><h1>Lending Operations <span style="color:#9edfdc">&amp; Controls</span></h1><p>Where does rework originate, which service levels are affected, and what would upstream validation change? Evidence-led workflow assessment, with assumptions kept separate from actual observations.</p></header><main>
<div class="toolbar"><div class="controls"><label class="control">BUSINESS SEGMENT<select id="seg"><option value="All">All segments</option><option>Retail</option><option>SME</option><option>Auto</option><option>Mortgage</option></select></label><label class="control">OPERATIONS TEAM<select id="team"><option value="All">All teams</option><option>North</option><option>Central</option><option>East</option><option>West</option></select></label><label class="control">REPORTING MONTH<select id="month"><option value="All">All months</option></select></label></div><span class="tag">SIMULATED DATA · JAN–OCT 2026</span></div>
<div class="kpis"><div class="card"><div class="cap">Cases processed</div><div class="val" id="k_cases">—</div><div class="note">Filtered lending operations</div></div><div class="card"><div class="cap">Exception rate</div><div class="val" id="k_exceptions">—</div><div class="note">Cases requiring intervention</div></div><div class="card"><div class="cap">SLA breach rate</div><div class="val" id="k_sla">—</div><div class="note">Cases over segment-specific SLA</div></div><div class="card"><div class="cap">Review effort</div><div class="val" id="k_review">—</div><div class="note">Total manual-review hours</div></div><div class="card"><div class="cap">First-pass yield</div><div class="val" id="k_fpy">—</div><div class="note">Cases without exceptions</div></div></div>
<div class="grid"><section class="panel"><h2>Monthly operating performance</h2><p class="sub">Volume vs. exception rate · observe whether quality holds as workload changes</p><div id="trend" class="chart"></div></section><section class="panel"><h2>Exception exposure by segment</h2><p class="sub">Exception rate and volume across lending products</p><div id="segmentChart" class="chart"></div></section><section class="panel"><h2>Where review time is spent</h2><p class="sub">Root-cause Pareto · full portfolio; not affected by segment/team/month filters</p><div id="causeChart" class="chart"></div></section><section class="panel"><h2>Team comparison</h2><p class="sub">SLA breaches as a share of cases, filtered by segment and month</p><div id="teamChart" class="chart"></div></section></div>
<div class="lower"><section class="panel"><h2>What-if: upstream validation <span class="badge">MODELED, NOT REALIZED</span></h2><p class="sub">Scenario for three addressable exception causes: missing documents, source mismatches, duplicate submissions</p><div class="sliders"><label class="control">PREVENTION OF ELIGIBLE EXCEPTIONS: <strong id="rateLabel">45%</strong><input id="rate" type="range" min="0" max="75" value="45" step="5"></label><label class="control">MINUTES AVOIDED PER PREVENTED EXCEPTION: <strong id="minuteLabel">24 min</strong><input id="minutes" type="range" min="5" max="40" value="24" step="1"></label></div><div class="scenario"><div><small>Preventable exceptions (modeled)</small><b id="s_prevented">—</b></div><div><small>Review hours saved (modeled)</small><b id="s_hours">—</b></div><div><small>Total review-effort reduction</small><b id="s_pct">—</b></div></div><div class="note-block">This is a <b>scenario, not an observed before/after outcome</b>. Eligible cases and baseline effort come from generated data. Prevention rate and minutes avoided are editable assumptions. No claim is made that SLA breaches fall by the same percentage.</div></section><section class="panel"><h2>Management recommendation</h2><p class="sub">A small, testable control rollout — not a broad systems overhaul</p><div class="steps"><div class="step"><span class="num">01</span><div><b>Shift checks upstream</b><p>Validate documents, record identifiers, and duplicate submissions before analyst review</p></div></div><div class="step"><span class="num">02</span><div><b>Pilot with a measurable control group</b><p>Track first-pass yield, review effort, SLA breaches, and false-positive flags by segment</p></div></div><div class="step"><span class="num">03</span><div><b>Define ownership and adoption</b><p>Assign exception categories, approve SOP changes, run UAT, and hand off a short operating guide</p></div></div></div></section></div>
<footer>Case study by Ishika Gupta · Reproducible simulated dataset · Assumptions and limitations documented in the repository · No confidential data</footer></main>
<script>/*PLOTLY_LIB*/</script><script>
const A=/*AGG*/,C=/*CAUSES*/,M=/*METRICS*/;
const $=id=>document.getElementById(id);const fmt=n=>Math.round(n).toLocaleString('en-CA');const pct=n=>`${n.toFixed(1)}%`;
const palette={teal:'#137f82',navy:'#243d5c',light:'#84c9c2',orange:'#d18a4f',purple:'#7081bb'};
const layout=(extra={})=>({font:{family:'-apple-system,BlinkMacSystemFont,Segoe UI,Arial',color:'#4c5d73',size:11},margin:{t:12,r:12,b:46,l:44},paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',showlegend:false,...extra});
const cfg={displayModeBar:false,responsive:true};
const months=[...new Set(A.map(r=>r.month))].sort();months.forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=m;$('month').appendChild(o)});
function sum(rows,key){return rows.reduce((s,r)=>s+Number(r[key]),0)}
function group(rows,key){const d={};rows.forEach(r=>{const k=r[key]; if(!d[k])d[k]={cases:0,exceptions:0,sla_breaches:0,review_minutes:0,eligible:0};for(const v of Object.keys(d[k]))d[k][v]+=+r[v]});return d}
function update(){const f=A.filter(r=>($('seg').value==='All'||r.segment===$('seg').value)&&($('team').value==='All'||r.team===$('team').value)&&($('month').value==='All'||r.month===$('month').value));const n=sum(f,'cases'),e=sum(f,'exceptions'),s=sum(f,'sla_breaches'),review=sum(f,'review_minutes'),eligible=sum(f,'eligible');$('k_cases').textContent=fmt(n);$('k_exceptions').textContent=pct(n?100*e/n:0);$('k_sla').textContent=pct(n?100*s/n:0);$('k_review').textContent=fmt(review/60)+'h';$('k_fpy').textContent=pct(n?100*(n-e)/n:0);
 const byMonth=group(f,'month');const mx=Object.keys(byMonth).sort();Plotly.react('trend',[{x:mx,y:mx.map(m=>byMonth[m].cases),name:'Volume',type:'bar',marker:{color:palette.light},hovertemplate:'%{x}<br>%{y:,} cases<extra></extra>'},{x:mx,y:mx.map(m=>100*byMonth[m].exceptions/byMonth[m].cases),name:'Exception rate',yaxis:'y2',mode:'lines+markers',line:{color:palette.orange,width:3},hovertemplate:'%{x}<br>%{y:.1f}% exceptions<extra></extra>'}],layout({showlegend:true,legend:{orientation:'h',y:1.18,x:0},yaxis:{title:'Cases',gridcolor:'#edf0f4',zeroline:false},yaxis2:{title:'Exception %',overlaying:'y',side:'right',rangemode:'tozero'},margin:{t:36,r:50,b:45,l:45}}),cfg);
 const bySegment=group(f,'segment');const segs=Object.keys(bySegment).sort();Plotly.react('segmentChart',[{x:segs,y:segs.map(g=>bySegment[g].cases?100*bySegment[g].exceptions/bySegment[g].cases:0),type:'bar',marker:{color:palette.teal},customdata:segs.map(g=>bySegment[g].exceptions),hovertemplate:'%{x}<br>%{y:.1f}% exception rate<br>%{customdata:,} exceptions<extra></extra>'}],layout({yaxis:{title:'Exception rate %',gridcolor:'#edf0f4',rangemode:'tozero'},margin:{t:14,r:10,b:45,l:50}}),cfg);
 const teams=group(f,'team');const ts=Object.keys(teams).sort();Plotly.react('teamChart',[{x:ts,y:ts.map(t=>teams[t].cases?100*teams[t].sla_breaches/teams[t].cases:0),type:'bar',marker:{color:palette.purple},hovertemplate:'%{x}<br>%{y:.1f}% SLA breaches<extra></extra>'}],layout({yaxis:{title:'SLA breach %',gridcolor:'#edf0f4',rangemode:'tozero'},margin:{t:14,r:10,b:45,l:45}}),cfg);
 const rate=Number($('rate').value)/100,minutes=Number($('minutes').value);$('rateLabel').textContent=pct(rate*100);$('minuteLabel').textContent=minutes+' min';$('s_prevented').textContent=fmt(eligible*rate);$('s_hours').textContent=fmt(eligible*rate*minutes/60)+'h';$('s_pct').textContent=pct(review?100*eligible*rate*minutes/review:0);
}
const roots=C.filter(c=>c.root_cause!=='None').sort((a,b)=>b.review_minutes-a.review_minutes);Plotly.newPlot('causeChart',[{y:roots.map(r=>r.root_cause).reverse(),x:roots.map(r=>r.review_minutes/60).reverse(),type:'bar',orientation:'h',marker:{color:palette.orange},hovertemplate:'%{y}<br>%{x:,.0f} review hours<extra></extra>'}],layout({xaxis:{title:'Review hours',gridcolor:'#edf0f4',rangemode:'tozero'},margin:{t:10,r:12,b:46,l:135}}),cfg);
['seg','team','month','rate','minutes'].forEach(id=>$(id).addEventListener(id==='rate'||id==='minutes'?'input':'change',update));update();
</script></body></html>'''
html=html.replace('/*PLOTLY_LIB*/',get_plotlyjs()).replace('/*AGG*/',json.dumps(agg,separators=(',',':'))).replace('/*CAUSES*/',json.dumps(causes,separators=(',',':'))).replace('/*METRICS*/',json.dumps(metrics,separators=(',',':')))
out=ROOT/'dashboard'/'index.html';out.write_text(html,encoding='utf-8')
print('Dashboard generated:',out,'bytes:',out.stat().st_size)
